def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    by_category = {}
    currency = None

    for entry in entries:
        entry_month = f"{entry.day.year}-{entry.day.month:02d}"
        if entry_month != month:
            continue

        # Check currency consistency
        if currency is None:
            currency = entry.currency
        elif currency != entry.currency:
            raise ValueError("Multiple currencies in same month")

        # Accumulate by category
        if entry.category not in by_category:
            by_category[entry.category] = Decimal('0')
        by_category[entry.category] += entry.amount

    # Filter out zero totals and sort by total ascending (so largest expense first),
    # with ties broken by category name
    filtered = {k: v for k, v in by_category.items() if v != Decimal('0')}
    return sorted(filtered.items(), key=lambda x: (x[1], x[0]), reverse=True)

